const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helpers
  const getVal = (obj) =>
    new Promise((resolve, reject) => {
      obj.evaluate((v, err) => (err ? reject(err) : resolve(v)));
    });

  // 1. Geometry & Time Definitions (Mount Stanley, Rwenzori)
  const region = ee.Geometry.Point([29.879, 0.389]).buffer(6000); // ~6 km buffer
  const scale = 1000; // Use >=1000m to avoid timeouts

  const periods = [
    { label: '2020', start: '2020-01-01', end: '2020-12-31' },
    { label: '2024', start: '2024-01-01', end: '2024-12-31' },
  ];

  // 2. Collections and masking
  function maskS2SR(img) {
    const scl = img.select('SCL');
    const mask = scl.neq(0)
      .and(scl.neq(1))
      .and(scl.neq(3))
      .and(scl.neq(7))
      .and(scl.neq(8))
      .and(scl.neq(9))
      .and(scl.neq(10)); // keep snow/ice (11)
    return img.updateMask(mask);
  }
  function addNDSI(img) {
    const ndsi = img.normalizedDifference(['B3', 'B11']).rename('NDSI');
    return img.addBands(ndsi);
  }
  function maskS2TOA(img) {
    const qa = img.select('QA60');
    const cloudBit = 1 << 10;
    const cirrusBit = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBit).eq(0).and(qa.bitwiseAnd(cirrusBit).eq(0));
    return img.updateMask(mask);
  }

  async function getMetrics(start, end) {
    // Try Sentinel-2 SR first
    let dataset = 'S2_SR';
    let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(start, end)
      .filter(ee.Filter.lte('CLOUDY_PIXEL_PERCENTAGE', 80));

    let size = await getVal(col.size());
    if (size === 0) {
      // Fallback to Sentinel-2 TOA
      dataset = 'S2_TOA';
      col = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
        .filterBounds(region)
        .filterDate(start, end)
        .filter(ee.Filter.lte('CLOUDY_PIXEL_PERCENTAGE', 80));
      size = await getVal(col.size());
      if (size === 0) {
        return { status: 'C1', info: 'Empty Collection', dataset, images: 0 };
      }
    }

    let processed;
    if (dataset === 'S2_SR') {
      processed = col.map(maskS2SR).map(addNDSI);
    } else {
      processed = col.map(maskS2TOA).map(addNDSI);
    }

    // Median composite
    const median = processed.median();

    // Valid pixel counts vs total (approximate cloudiness)
    const totalPix = await getVal(
      ee.Image.constant(1)
        .rename('one')
        .reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: scale,
          maxPixels: 1e9,
        })
        .get('one')
    );
    const validPix = await getVal(
      median
        .select('NDSI')
        .reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: scale,
          maxPixels: 1e9,
        })
        .get('NDSI')
    );

    if (!totalPix || totalPix === 0) {
      return { status: 'C3', info: 'Invalid total pixel count', dataset, images: size };
    }
    if (!validPix || validPix === 0) {
      return {
        status: 'C2',
        info: 'No Valid Pixels after masking',
        dataset,
        images: size,
        totalPix,
        validPix,
        cloudPct: 100.0,
      };
    }
    const cloudPct = 100.0 * (1.0 - validPix / totalPix);

    // Snow/Ice area using NDSI threshold
    const snowMask = median.select('NDSI').gt(0.4).and(median.select('B3').gt(0.2)).rename('snow');
    const snowImg = snowMask.selfMask();
    let snowAreaM2 = await getVal(
      snowImg
        .multiply(ee.Image.pixelArea())
        .reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: region,
          scale: scale,
          maxPixels: 1e9,
        })
        .get('snow')
    );
    if (snowAreaM2 === null || snowAreaM2 === undefined) snowAreaM2 = 0;
    if (!isFinite(snowAreaM2) || snowAreaM2 < 0) {
      return { status: 'C3', info: 'Invalid snow area', dataset, images: size };
    }

    return {
      status: 'OK',
      dataset,
      images: size,
      totalPix,
      validPix,
      cloudPct,
      snowAreaM2,
      snowAreaHa: snowAreaM2 / 10000.0,
    };
  }

  try {
    const m2020 = await getMetrics(periods[0].start, periods[0].end);
    const m2024 = await getMetrics(periods[1].start, periods[1].end);

    // Handle failure cases
    if (m2020.status === 'C1' || m2024.status === 'C1') {
      console.log(`2020 Images: ${m2020.images || 0} (${m2020.dataset || 'NA'})`);
      console.log(`2024 Images: ${m2024.images || 0} (${m2024.dataset || 'NA'})`);
      console.log('Empty Collection in at least one period.');
      console.log('C1');
      return;
    }
    if (m2020.status === 'C2' || m2024.status === 'C2') {
      if (m2020.status === 'OK') {
        console.log(
          `2020 ${m2020.dataset} Images: ${m2020.images}, ValidPix: ${m2020.validPix}/${m2020.totalPix} (Cloud: ${m2020.cloudPct.toFixed(
            1
          )}%), Snow ha: ${m2020.snowAreaHa.toFixed(2)}`
        );
      } else {
        console.log(`2020 Images: ${m2020.images || 0} (${m2020.dataset || 'NA'})`);
      }
      if (m2024.status === 'OK') {
        console.log(
          `2024 ${m2024.dataset} Images: ${m2024.images}, ValidPix: ${m2024.validPix}/${m2024.totalPix} (Cloud: ${m2024.cloudPct.toFixed(
            1
          )}%), Snow ha: ${m2024.snowAreaHa.toFixed(2)}`
        );
      } else {
        console.log(`2024 Images: ${m2024.images || 0} (${m2024.dataset || 'NA'})`);
      }
      console.log('No valid pixels after masking in at least one period.');
      console.log('C2');
      return;
    }
    if (m2020.status === 'C3' || m2024.status === 'C3') {
      console.log('Calculation failure detected.');
      console.log('C3');
      return;
    }

    // Evidence output (concise)
    console.log(
      `2020 ${m2020.dataset} Images: ${m2020.images}, ValidPix: ${m2020.validPix}/${m2020.totalPix} (Cloud: ${m2020.cloudPct.toFixed(
        1
      )}%)`
    );
    console.log(`2020 Snow area (ha): ${m2020.snowAreaHa.toFixed(2)}`);

    console.log(
      `2024 ${m2024.dataset} Images: ${m2024.images}, ValidPix: ${m2024.validPix}/${m2024.totalPix} (Cloud: ${m2024.cloudPct.toFixed(
        1
      )}%)`
    );
    console.log(`2024 Snow area (ha): ${m2024.snowAreaHa.toFixed(2)}`);

    // 5. Decision logic
    const a2020 = m2020.snowAreaHa;
    const a2024 = m2024.snowAreaHa;
    const delta = a2020 - a2024;
    const rel = a2020 > 0 ? (delta / a2020) * 100.0 : (a2024 === 0 ? 0 : -100);
    console.log(`Δ Snow (ha): ${delta.toFixed(2)} (${rel.toFixed(1)}% of 2020)`);

    // Decrease if 2024 < 2020 by at least max(5% of 2020, 1 ha)
    const tol = Math.max(0.05 * a2020, 1.0);
    const decreased = a2024 + tol < a2020;

    console.log(decreased ? 'A' : 'B');
  } catch (e) {
    console.error('Error:', e.message || e);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
